/* furn.h - the furniture catalog record and its enums.
 *
 * CONTRACT (docs/design/story/SPEC.md sec.4): written by S0, maintained by H1
 * (add-only). The rows are generated by core/tools/furngen.c (H4) from
 * core/data/furn/catalog.txt (H1: stats) joined with core/data/furn/art/
 * (H4: prims) into core/gen/furn_data.c (the PS1 `home` overlay group) and
 * core/gen/furn_grant.c (resident {unlock -> furn} table, SPEC C3).
 *
 * Ids are append-only and saved as 9 bits (SPEC R9: FURN_MAX 384). Only
 * code inside the home group may touch doomo_furn[] (SPEC C6); story code
 * goes through house_api.h.
 */
#ifndef DOOMO_FURN_H
#define DOOMO_FURN_H

#include "types.h"

#define FURN_MAX   384          /* ids 0..383, 9 bits in the save          */
#define FURN_NONE  0x1FF        /* the 9-bit "no piece"                    */

/* Catalog categories (HF sec.8.1). Append only. */
enum { FCAT_PASTEL, FCAT_GOTHIC, FCAT_HELLISH, FCAT_PLUSH, FCAT_KITCHEN,
       FCAT_TECH, FCAT_GARDEN, FCAT_LIGHT, FCAT_WALL, FCAT_RUG, FCAT_TROPHY,
       FCAT_SEASONAL, FCAT_STORY, FCAT_COUNT };

/* DoomoFurn.flags */
enum { FF_WALL = 1, FF_RUG = 2, FF_SURFACE = 4, FF_SMALL = 8, FF_LIGHT = 16,
       FF_ANIM = 32, FF_HELL = 64, FF_BILLBOARD = 128 };
/* DoomoFurn.flags2 (SPEC sec.4) */
enum { FF_PORTAL = 1,       /* a door: fixed slot, re-skin only            */
       FF_CURSED = 2,       /* tape-stops the vamp when it lands           */
       FF_NO_SQUASH = 4,    /* hell props never wobble (SF sec.15.4)          */
       FF_UNSELLABLE = 8,   /* gifts, trophies, story pieces (cap 1)       */
       FF_GIFT = 16,        /* placed by a citizen; `giver` is valid       */
       FF_STARTER = 32,     /* (H1) granted when the player moves in       */
       FF_FIXED = 64 };     /* (H1 M3) a decal nobody places or picks up: the
                               Ch2 wallpaper eye (it still scores)          */

/* Interactions (FI_*): what Live mode does with a piece. */
enum { FI_NONE, FI_SIT, FI_SLEEP, FI_EAT, FI_COOK, FI_PLAY, FI_WATCH, FI_MUSIC,
       FI_READ, FI_BATHE, FI_PRAY, FI_SUMMON, FI_EXAMINE, FI_TURRET, FI_COUNT };

/* Themes (HF sec.2.3): each is a 6-byte ROM record in themes.txt (H1). */
enum { THEME_PASTEL, THEME_CLOUD, THEME_CANDY, THEME_COTTAGE, THEME_GOTH,
       THEME_BONE, THEME_LAVA, THEME_VAPOR, THEME_PICNIC, THEME_WORKSHOP,
       THEME_COUNT };
#define THEME_NONE 0xFF

typedef struct DoomoFurn {
    const char *name, *desc;          /* <= 20 / <= 40 chars                       */
    uint16_t price;                   /* H$, 0 = gift / story only                 */
    uint16_t unlock;                  /* unlock id gate (any team's range), 0xFFFF open */
    uint16_t giver;                   /* resident id for FF_GIFT pieces, 0xFFFF none */
    uint8_t  cat, flags, flags2, interact; /* FCAT_*, FF_*, FF_* (flags2), FI_*   */
    uint8_t  fw, fd, fh;              /* footprint tiles 1..4, height px/4          */
    uint8_t  paint_a, paint_b;        /* default paints, 0xFF = fixed               */
    int8_t   cute, spooky, comfy;     /* score contributions                        */
    uint8_t  need;                    /* resident.h STAT_* restored by FI_* use, 0xFF none */
    uint8_t  seat_dz, light_r;        /* seat/sleep offset, lamp radius (tiles)     */
    uint8_t  theme;                   /* THEME_* (for Style / Harmony)              */
    uint8_t  mass;                    /* barricade HP contribution (0 = none)       */
    uint8_t  nprim;                   /* recipe in doomo_furn_prims[]               */
    uint16_t prim0;
    uint8_t  frames;                  /* GBA animation frames                       */
    uint8_t  role;                    /* (H1, add-only) FR_*: what the score and the
                                         placement rules recognise the piece as   */
} DoomoFurn;

/* Generated tables (furngen, H4). Weak empty defaults: core/src/stubs.c. */
extern const DoomoFurn doomo_furn[];
extern const uint16_t  doomo_furn_count;

/* ---- H1 additions (add-only) ------------------------------------------------ */

/* DoomoFurn.role: the pieces the score's feng-shui rules (HF sec.4.2), the
 * fixed room slots and the defence know by name. Append only. */
enum { FR_NONE, FR_DOOR, FR_WINDOW, FR_HEARTH, FR_BED, FR_SEAT, FR_TABLE,
       FR_LAMP, FR_CANDLE, FR_MIRROR, FR_PLUSH, FR_PENTAGRAM, FR_PLAIN_HUMAN,
       FR_TURRET, FR_PLATE, FR_NEST, FR_FENCE, FR_PLANT, FR_COUNT };

/* Paint slots of DoomoFurn.paint_a / paint_b: 0xFF = fixed colours. The art
 * marks slot A with PAINT_BUBBLEGUM's 3 shades and slot B with PAINT_MINT's
 * (HF sec.6.2); the renderers swap those 6 indices (and the two outline
 * shades below) for the chosen paints. */
#define FURN_MARK_A     7                /* PAINT_BUBBLEGUM */
#define FURN_MARK_B     15               /* PAINT_MINT      */
#define FURN_PAINT_DEFAULT 0x1F          /* HomeObj paint: the catalog default */

/* PS1 / furngen recipe primitives (HF sec.6.2, 7.1): one 8-byte record each,
 * in units of 1/16 tile (x, y) and pixels (z). doomo_furn[i].prim0 / nprim
 * index doomo_furn_prims[]. */
enum { FP_BOX, FP_BLOB, FP_CYL, FP_CONE, FP_COUNT };
enum { FM_A = 0xF0, FM_B = 0xF1 };       /* FurnPrim.mat: paint slot A / B;
                                            otherwise a palette index (base tone) */
enum { FPS_SOFT = 1, FPS_SHINY = 2 };   /* style bits (kind bits 2-3) */
#define FURN_PRIM_KIND(p)   ((p)->kind & 3)
#define FURN_PRIM_STYLE(p)  (((p)->kind >> 2) & 3)
#define FURN_PRIM_FRAMES(p) ((p)->kind >> 4)  /* 0 = every frame */
typedef struct DoomoFurnPrim {
    uint8_t kind;                     /* bits 0-1 FP_*, 2-3 FPS_*, 4-7 frame mask (0 = all) */
    uint8_t mat;                      /* FM_A / FM_B / palette index                   */
    int8_t  x, y;                     /* box: min corner; others: centre (units)       */
    uint8_t z;                        /* bottom (px)                                   */
    uint8_t w, d, h;                  /* box: size; blob: diameters; cyl/cone: diameter,
                                         0, height                                     */
} DoomoFurnPrim;                      /* 8 B */
extern const DoomoFurnPrim doomo_furn_prims[];

/* GBA / native iso sprites (furngen -> core/gen/furn_iso.c; the PS1 links an
 * empty table, SPEC C3). Each facing is span encoded: h u16 row offsets
 * (relative to `off`), then per row runs of [skip u8][len u8][len pixels],
 * ended by skip = 0xFF. (ox, oy) is where the footprint's back corner
 * (tile origin, z = 0) lands in the image. Entry of (furn, frame, facing):
 * doomo_furn_iso_first[furn] + frame * 2 + facing, facing 0 = rot 0 (front
 * faces +y), 1 = rot 1 (front faces +x); rot 2 / 3 draw facing 1 / 0
 * mirrored (IMG_FLIPX). The second table is the cheap box fallback colours. */
typedef struct DoomoFurnIso {
    uint8_t  w, h, ox, oy;
    uint32_t off;                     /* into doomo_furn_iso_data[]                    */
} DoomoFurnIso;
extern const DoomoFurnIso doomo_furn_iso[];
extern const uint16_t     doomo_furn_iso_first[];  /* [doomo_furn_count]          */
extern const uint8_t      doomo_furn_iso_data[];
extern const uint16_t     doomo_furn_iso_count;    /* 0 on the PS1                 */

/* Resident grant table (furngen -> core/gen/furn_grant.c, SPEC C3): the
 * pieces an unlock id grants (trophies), their toast names, and which
 * pieces are capped at one (trophies, story pieces, gifts). */
typedef struct DoomoFurnGrant { uint16_t unlock, furn; const char *name; } DoomoFurnGrant;
extern const DoomoFurnGrant doomo_furn_grants[];   /* terminated by name == NULL  */
extern const uint8_t        doomo_furn_cap1[FURN_MAX / 8];

/* ---- H1 M3 additions (add-only): themes, blueprints, decorate-for layouts --
 * Generated by furngen into core/gen/furn_data.c (the PS1 `home` group) from
 * core/data/home/themes.txt, blueprints.txt (H1) and layouts_*.txt (the
 * content packages, SPEC R19). A theme is HF sec.2.3's record with the wall
 * and floor paints spelled out. */
typedef struct DoomoHomeTheme {
    const char *name;
    uint8_t wallpaper, floor;          /* patterns 0..31                            */
    uint8_t wall_paint, floor_paint;   /* PAINT_*                                   */
    uint8_t paint_a, paint_b;          /* what free paint slots are recoloured to    */
    uint8_t ceiling, accent;           /* ceiling tint 0..7, an accent PAINT_*      */
} DoomoHomeTheme;
/* One piece of a blueprint or a layout. furn is a furniture id, or
 * HOME_PIECE_ROLE | FR_* for "any piece with this role" (layouts). rot uses
 * the save's rotations: 0 faces +y (S), 1 +x (E), 2 -y (N), 3 -x (W). */
#define HOME_PIECE_ROLE 0x8000u
typedef struct DoomoHomePiece {
    uint16_t furn;
    uint8_t  x, y, rot;
    uint8_t  pa, pb;                   /* PAINT_* or FURN_PAINT_DEFAULT             */
    uint8_t  sub;                      /* half-tile sub-position (smalls on surfaces) */
} DoomoHomePiece;                      /* 8 B */
typedef struct DoomoHomeSet {
    const char *name;
    uint16_t first;                    /* into doomo_home_pieces[]                  */
    uint8_t  n, room;                  /* pieces; the HOME_ROOM_* it was made for    */
    uint8_t  id;                       /* layouts: the saved id 1..15 (4 bits)       */
    uint8_t  theme;                    /* blueprints: THEME_* or THEME_NONE          */
    uint8_t  tol, need;                /* layouts: tolerance (tiles), pieces to match */
} DoomoHomeSet;
extern const DoomoHomeTheme doomo_home_themes[THEME_COUNT];
extern const DoomoHomePiece doomo_home_pieces[];
extern const DoomoHomeSet   doomo_home_blueprints[];
extern const uint8_t        doomo_home_blueprint_count;
extern const DoomoHomeSet   doomo_home_layouts[];
extern const uint8_t        doomo_home_layout_count;

#endif
